// This script is generated by Gemini
using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections; 

public class RainManager : MonoBehaviour
{
    [Header("Phase Timers")]
    public float prepTime = 60f; 
    private float currentTimer = 0f;
    public bool isRaining = false;
    
    // NEW: Prevents the GameOver function from looping
    private bool isGameOver = false;

    [Header("Water Objects & Limits")]
    public Transform waterCube;
    public float minWaterY = -0.5f;   
    public float maxWaterY = 2.0f;    
    public float baseWaterSpeed = 0.1f; 

    [Header("Drainages")]
    public DrainageNode[] drainages;

    [Header("Rain Visuals & Audio")]
    public ParticleSystem rainParticles;
    public AudioSource rainAudio;
    public float fadeDuration = 2f;
    public float maxVolume = 1f;

    void Start()
    {
        Vector3 startPos = waterCube.position;
        startPos.y = minWaterY;
        waterCube.position = startPos;

        if (rainParticles != null) rainParticles.Stop();
        if (rainAudio != null) rainAudio.volume = 0f;
    }

    void Update()
    {
        // Stop running all logic if the game has already ended
        if (isGameOver) return;

        // 1. Handle Prep Phase
        if (!isRaining)
        {
            currentTimer += Time.deltaTime;
            if (currentTimer >= prepTime)
            {
                isRaining = true;
                Debug.Log("Prep time over! 3D Rain has started.");
                
                if (rainParticles != null) rainParticles.Play();

                if (rainAudio != null)
                {
                    rainAudio.Play();
                    StartCoroutine(FadeInAudio());
                }
            }
            return; 
        }

        // 2. Calculate Total Debris
        int totalDebris = 0;
        foreach (DrainageNode node in drainages)
        {
            if (node != null) totalDebris += node.obstacleLevel;
        }

        // 3. Move the Water
        float flowRate = (totalDebris - 10f) * baseWaterSpeed;
        Vector3 newPos = waterCube.position;
        newPos.y += flowRate * Time.deltaTime;
        newPos.y = Mathf.Max(newPos.y, minWaterY);
        waterCube.position = newPos;

        // 4. Check for Game Over (Now protected by the boolean flag)
        if (waterCube.position.y >= maxWaterY)
        {
            GameOver();
        }
    }

    private IEnumerator FadeInAudio()
    {
        float elapsedTime = 0f;
        while (elapsedTime < fadeDuration)
        {
            elapsedTime += Time.deltaTime;
            rainAudio.volume = Mathf.Lerp(0f, maxVolume, elapsedTime / fadeDuration);
            yield return null;
        }
        rainAudio.volume = maxVolume; 
    }

    void GameOver()
    {
        // Lock the flag so this can never be called a second time
        isGameOver = true;
        Debug.Log("Game Over! Opening Menu...");
        GameMenu.Instance.GameOver();
    }
}